/**
 * Writes scripts/data/dubai-essential-drug-list-formulary-submission.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-dedl-formulary-cover.mjs.
 *
 *   node scripts/generate-dedl-formulary-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/dubai-essential-drug-list-formulary-submission.json');

export const SARAH_CHEN_SANITY_ID = '498ba300-bfab-4a76-b256-b2139d4d66fe';

/** Every blogPost field that applies to a healthcare-silo article. */
export const DEDL_FORMULARY_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-dubai-essential-drug-list-formulary-submission.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.DEDL_FORMULARY_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.DEDL_FORMULARY_BODY_HTML.split('<h2')[0])
    .replace(/^A Dubai Essential Drug List formulary submission[\s\S]*?This briefing uses only published sources\./, '')
    .trim();

  return {
    seo: {
      metaTitle: mod.DEDL_FORMULARY_META_TITLE,
      metaDescription: mod.DEDL_FORMULARY_META_DESCRIPTION,
      focusKeyword: 'Dubai Essential Drug List formulary submission',
      keywords: [
        'Dubai Essential Drug List formulary submission',
        'Dubai Essential Drug List',
        'Dubai Drug Code',
        'Essential Benefits Plan',
        'UAE formulary listing',
        'DHA formulary',
        'UAE market access research',
        'real-world evidence UAE',
      ],
      canonicalUrl: mod.DEDL_FORMULARY_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.DEDL_FORMULARY_META_TITLE,
      ogDescription: mod.DEDL_FORMULARY_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.DEDL_FORMULARY_COVER_IMAGE}`,
        alt: mod.DEDL_FORMULARY_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.DEDL_FORMULARY_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.DEDL_FORMULARY_SLUG },
    excerpt: mod.DEDL_FORMULARY_EXCERPT,
    publishedAt: mod.DEDL_FORMULARY_PUBLISHED_ISO,
    updatedAt: mod.DEDL_FORMULARY_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: SARAH_CHEN_SANITY_ID,
      name: 'Sarah Chen',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.DEDL_FORMULARY_HERO_IMAGE}`,
      alt: mod.DEDL_FORMULARY_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for Dubai Essential Drug List formulary submission',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.DEDL_FORMULARY_TAGS],
    country: 'United Arab Emirates',
    language: 'en',
    readingTime: mod.DEDL_FORMULARY_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.DEDL_FORMULARY_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.DEDL_FORMULARY_EXECUTIVE_SUMMARY_HTML}\n\n${mod.DEDL_FORMULARY_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'What a Dubai Essential Drug List formulary submission should measure',
        type: 'table',
        data: JSON.stringify(
          mod.DEDL_FORMULARY_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'GC 12/2018; GC 03/2024; EDE Decision 47/2025; DOH RWE 2023; DOH HTA 2025',
      },
      portableText(
        firstParagraph ||
          'A Dubai Essential Drug List formulary submission is a research problem before it is a portal upload.',
      ),
    ],
    faq: mod.DEDL_FORMULARY_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: [
      'uae-drug-pricing-ede-takeover-launch-research',
      'thiqa-obesity-reimbursement-abu-dhabi',
      'iqvia-alternative-uae-primary-research',
    ],
    ctaSection: { ...mod.DEDL_FORMULARY_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.DEDL_FORMULARY_BODY_HTML),
    factCheckedAt: mod.DEDL_FORMULARY_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/dubai-essential-drug-list-formulary-submission-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of DEDL_FORMULARY_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(`Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
